const t = (zh, ja, en) => ({ zh, ja, en });
/** 选择题 */
const C = (ref, prompt, options, answer, hint, explain, extra = {}) => ({ type: 'choice', ref, prompt, options, answer, hint, explain, ...extra });
/** 填空题：prompt 里用 ___，answer 是 bank 的 id 顺序 */
const F = (ref, prompt, bank, answer, hint, explain, extra = {}) => ({ type: 'fill', ref, prompt, bank, answer, hint, explain, ...extra });
/** 连线题 */
const M = (ref, prompt, pairs, hint, explain, extra = {}) => ({ type: 'match', ref, prompt, pairs, hint, explain, ...extra });
/** 一题：mode 绑定方式、card 题卡、lines 出题台词（多版本）、right / wrong 这一题专用的反应（可选）、phase 转折题 */
